  grammar: {
    title: 'Unit 13 Complete Synthesis & Integrated Mastery',
    concept: 'Review and mastery of all Unit 13 communicative grammar systems: relative pronouns (who/which/where), conditionals (unless/as long as), past continuous vs simple (while/as), passive voice, indirect questions, correlative conjunctions, culinary imperatives, and used to / would.',
    patterns: [
      {
        title: 'Mastery Checklist: Relative Clauses & Conditionals',
        structure: 'Noun + [who / which / where] ... | Unless + Present, Future',
        rule: 'Combine defining descriptors and conditional safeguards seamlessly in complex discourse.',
        examples: [
          { en: 'This is the national park where rare birds nest, and they will thrive unless pollution increases.', hi: 'यह वह राष्ट्रीय उद्यान है जहाँ दुर्लभ पक्षी घोंसला बनाते हैं, और वे तब तक फलते-फूलते रहेंगे जब तक प्रदूषण नहीं बढ़ता।', es: 'Este es el parque nacional donde anidan aves raras, y prosperarán a menos que aumente la contaminación.' }
        ]
      },
      {
        title: 'Mastery Checklist: Passive Voice & Indirect Inquiries',
        structure: 'Object + [is / was + Past Participle] | Could you tell me where [Subject + Verb]?',
        rule: 'Use polite inquiries and objective passive reporting in professional and cultural contexts.',
        examples: [
          { en: 'Could you explain how the festival is celebrated by local communities?', hi: 'क्या आप समझा सकते हैं कि स्थानीय समुदायों द्वारा यह त्योहार कैसे मनाया जाता है?', es: '¿Podría explicar cómo celebran el festival las comunidades locales?' }
        ]
      },
      {
        title: 'Mastery Checklist: Correlatives & Purpose Connectors',
        structure: 'Both ... and ... | in order to + Base Verb / so that + Clause',
        rule: 'Join parallel ideas and articulate goals with precision.',
        examples: [
          { en: 'We study both classical literature and modern cinema in order to understand cultural evolution.', hi: 'हम सांस्कृतिक विकास को समझने के लिए शास्त्रीय साहित्य और आधुनिक सिनेमा दोनों का अध्ययन करते हैं।', es: 'Estudiamos tanto la literatura clásica como el cine moderno para comprender la evolución cultural.' }
        ]
      }
    ]
  },
